"""Freeze scientific choices before any new optimizer/ranking evaluation."""
from .common import *
import statistics,itertools
FULL=ROOT/'results/module14f_memory_ocr_x3/heavy_empirical_x3_reconciled.json'
COMMON=ROOT/'results/module18_cross_task/controlled_common_G_pool.json'
TASKS=['text','image','ocr','asr','lid','visual_qa']
def main():
 assert not (OUT/'utility_definition.json').exists(),'Scientific freeze is immutable; do not silently replace it.'
 weights={'Q':0.,'T':.25,'L':.30,'P':.30,'M':.15}
 grid=[{'id':f'L{l}_P{p}_M{m}','Q':0.,'T':.25,'L':l,'P':p,'M':m} for l,p,m in itertools.product([.15,.30,.45],[.15,.30,.45],[.05,.15,.30])]
 definition={'at_utc':now(),'formula':'U = wQ*Q_norm - wT*T_norm - wL*L_norm - wP*P_norm - wM*M_norm','weights':weights,'sensitivity_grid':grid,'quality':{'Q_norm':None,'mode':'hard_constraint_only','reason':'Accuracy, WER and OCR metrics have no direction-consistent cross-task cardinal utility calibration. wQ=0 disables quality reward; no missing scores filled.'},'L_norm':'sum(lambda_k/sum(lambda) * mean_E2E_k/ref_ms_k); offered weights frozen, never reweighted by completions','P_norm':'sum(lambda_k/sum(lambda) * P95_E2E_k/ref_ms_k); separate raw pooled-request P95 reported','T_norm':'1 - min(1, completed/offered, completed_in_window/(fixed_offered_QPS*planned_window_seconds)); stopped measurement retains planned denominator. Positive sustained queue growth invalidates U via hard stability constraint. Drain cannot erase throughput loss.','M_norm':'max(safe_factor*postwarm_idle_mean, safe_factor*postmeasurement_idle_mean)/frozen_budget; prediction uses reconciled safe table/budget','hard_constraints':['original quality/capability admission','all offered tasks covered','route conservation','only measured replica counts','safe memory <= budget','no runtime/errors/incomplete cohort','system and worker not unstable; recoverable only if original recovery confirmed and no sustained growth'],'unstable_policy':'U=null, eligible=false. Completed-only latency components retained as CENSORED diagnostic, never sortable. No artificial finite utility for unstable plans.','primary_tie_rule':'maximize predicted U, then smaller safe memory, then canonical JSON identity','positive_gain_rule':'delta_U > 0.01; positive means improvement against an explicit feasible same-workload comparator, never absolute U (cost-only U<=0)','holdout_support_rule':'At least 3 distinct independent matched workload/deployment-group contrasts across >=2 model combinations, >=80% ranking agreement, zero high-confidence reversals, >=80% stress-interval coverage. Module19 never independent validation.','selection_uncertainty':'Nominal maximum U among nominal rho<1 candidates; operational rho>0.8 and stress-unstable candidates remain visible as conditional, not certified stable or deployment-ready.'}
 save('utility_definition.json',definition)
 d=read(FULL);refs={t:statistics.median(p['service_time_ms'][t] for p in d['models'].values() if t in p['supported_tasks']) for t in TASKS}
 # Holdout is whole Module16 model-combination/workloads, not requests or repetitions.
 manifest={'at_utc':now(),'frozen_before_new_predictions':True,'latency_reference_ms':refs,'reference_rule':'Median admitted standalone service ms across full reconciled Heavy pool; same physical reference for mean and P95, not a tail SLO or measured P95 reference. Independent of Module19 outcome and Proposed labels.','reference_source':ref(FULL),'development_groups':['Module14F: profiles (g/M measured here cannot independently validate same profiles)','Module15: ASR two-task history','Module17: diagnostic/scoped capacity evidence only','Module18: cross-task histories','Module19: ALL cases including all negative and failed results'],'retrospective_holdout_groups':['Module16: entire full-pool six-task deployment combination and LOW/MID workloads, all repetitions together'],'holdout_limits':'Retrospective archival holdout, already reported publicly within project; no fitting to these observations, no blind/prospective claim. Only one deployment per offered workload exists: independent matched deployment-ranking sample count is zero. Module17 own holdout supports only its original scope.','task_pool':TASKS,'quality_policy':ref(ROOT/'results/module8b_quality_pool_finalization/quality_policy.json'),'model_pools':{'FULL_HEAVY_19':ref(FULL),'COMMON_G_17':ref(COMMON)},'budgets_mib':[17007.17405495223,27980.1894,49140.0],'background_QPS':{t:.2 if t=='visual_qa' else .1 for t in TASKS},'target_QPS_grid':{'text':[.1,1,5,20,40,60,100],'image':[.1,1,10,40,100,137.2973242711638,200],'lid':[.1,1,3,6,10,12,16],'asr':[.1,.5,1,2,3,4,6],'ocr':[.1,1,10,40,80,120,200]},'generator':{'method':'MILP linear normalized-service + safe-memory seeds; target G fractions [free,0,.01,.05,.2,.5,1], rho caps [.8,.95]; retain frozen historical candidates; generation weights main plus low/high memory; no phase restrictions','target_G_fractions':[None,0.,.01,.05,.2,.5,1.],'capacity_caps':[.8,.95],'generation_memory_weights':[.05,.15,.30],'milp_time_limit_seconds':2.,'MILP_mip_gap':.001,'completeness':'Heuristic candidate set; not an exhaustive utility optimum. Same deployment may host multiple Specialists; measured counts unmodified.'},'predictor':{'method':'120-second deterministic-periodic FIFO fluid-service replay with family round robin; path s0 * replicas/g(count). Constant service captures queue collisions; does not claim sample-tail model or transferable interference calibration.','phase_offsets':[.0,.37],'warmup_seconds':10.,'service_stress_multipliers':[1.,1.25,2.],'stress_interpretation':'Engineering scenarios, NOT fitted corrections, confidence intervals or measured bounds; no global Module17 transfer.','calibration':'No parameter fit to Module19 or holdout. Frozen independent standalone s0/g/M only. Relative ranking hypothesis tested separately.','structural_limit':'Constant service omits sample variability and cross-process interference; P95 and capacity carry high uncertainty.'},'three_phase_test':'For each pool/budget/target evaluate every QPS. Natural LOW reuses G with no target S; MID deploys target S with G fraction zero; HIGH mixed. Require LOW beats feasible S-only, MID beats feasible G-only, HIGH beats best feasible pure route by >0.01; all nominal constraints pass. Strict increasing LOW<MID<HIGH; optional stress robustness separate.','implementation':[ref(p) for p in sorted((ROOT/'module20').glob('*.py'))]}
 save('utility_reference_manifest.json',manifest)
 protected=[]
 for p in sorted((ROOT/'results').rglob('*')):
  if p.is_file() and OUT not in p.parents:protected.append(ref(p))
 for base in ['method_v1','method_v2','deployment_core','module9bc','module14f','module15','module16','module17','module18','module19']:
  protected += [ref(p) for p in sorted((ROOT/base).rglob('*.py'))]
 save('protected_before.json',protected)
 print('FROZEN',refs,'protected',len(protected),flush=True)
